upil_id) pupil_count FROM school_exams x JOIN schools s ON s.id=x.school_id LEFT JOIN school_classes c ON c.id=x.class_id LEFT JOIN pupil_results r ON r.school_id=x.school_id AND r.exam_name=x.name AND r.academic_year=x.academic_year AND (x.class_id IS NULL OR r.class_level=c.name) WHERE x.school_id IN ($marks) GROUP BY x.id,x.school_id,x.class_id,x.name,x.academic_year,s.name,c.name ORDER BY x.academic_year DESC,x.name");$q->execute($ids);$exams=$q->fetchAll();$q=$pdo->prepare("SELECT a.*,u.name teacher_name,s.name school_name FROM teacher_assignments a JOIN users u ON u.id=a.user_id JOIN schools s ON s.id=a.school_id WHERE a.school_id IN ($marks) AND a.active=1 ORDER BY s.name,a.class_level,a.subject");$q->execute($ids);$assignmentRows=$q->fetchAll();$assignmentGroups=[];foreach($assignmentRows as $assignmentRow){$groupKey=(int)$assignmentRow['school_id'].':'.(int)$assignmentRow['user_id'];if(!isset($assignmentGroups[$groupKey]))$assignmentGroups[$groupKey]=['teacher_name'=>$assignmentRow['teacher_name'],'school_name'=>$assignmentRow['school_name'],'school_id'=>(int)$assignmentRow['school_id'],'classes'=>[],'subjects'=>[],'assignments'=>[]];$assignmentGroups[$groupKey]['classes'][$assignmentRow['class_level']]=true;$assignmentGroups[$groupKey]['subjects'][$assignmentRow['subject']]=true;$assignmentGroups[$groupKey]['assignments'][]=$assignmentRow;}$assignments=array_values($assignmentGroups);}}catch(Throwable $ex){}
