ils></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><dialog class="academic-dialog academic-dialog-wide" id="pupils-directory-dialog" data-academic-dialog aria-labelledby="pupils-directory-title"><div class="academic-dialog-head"><div><div class="eyebrow">SCHOOL RECORDS</div><h2 id="pupils-directory-title">Pupils directory</h2><p class="muted">Search and review pupils registered in your school access.</p></div><button type="button" class="icon-button" data-close-academic-dialog aria-label="Close pupils directory">×</button></div><div class="academic-dialog-content"><section class="academic-list-section academic-directory-content" data-academic-list><div class="section-heading"><div><div class="eyebrow">PUPIL DIRECTORY</div><h2>Pupils</h2></div><span class="count-pill"><?=count($pupils)?> pupils</span></div><?php if($pupils):?><div class="academic-table-tools"><label class="sr-only" for="filter-pupils">Search pupils</label><input id="filter-pupils" type="search" data-academic-filter placeholder="Search name, admission or class" autocomplete="off"><span data-filter-status aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th>Admission</th><th>Pupil</th><th>School / class</th><th>Scholar type</th><th>Actions</th></tr></thead><tbody><?php foreach($pupils as $p):?><tr><td><?=e($p['admission_number'])?></td><td><?=e($p['first_name'].($p['middle_name']?' '.$p['middle_name']:'').' '.$p['last_name'])?></td><td><?=e($p['school_name'].' · '.$p['class_level'].($p['stream']?' / '.$p['stream']:''))?></td><td><?=e(ucfirst($p['scholar_type']))?></td><td><div class="academic-row-actions"><a class="button" href="results.php?pupil=<?=$p['id']?>">View results</a><?php if($canRegister):?><details class="academic-edit-assignment"><summary class="button">Edit</summary><form method="post" class="academic-async academic-edit-pupil-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="pupil_update"><input type="hidden" name="record_id" value="<?=$p['id']?>"><input type="hidden" name="school_id" value="<?=$p['school_id']?>"><label>Admission number</label><input name="admission_number" value="<?=e($p['admission_number'])?>" maxlength="60"><label>First name</label><input name="first_name" value="<?=e($p['first_name'])?>" required maxlength="80"><label>Middle name</label><input name="middle_name" value="<?=e($p['middle_name'])?>" maxlength="80"><label>Last name</label><input name="last_name" value="<?=e($p['last_name'])?>" required maxlength="80"><label>Class level</label><input name="class_level" value="<?=e($p['class_level'])?>" required maxlength="80"><label>Stream</label><input name="stream" value="<?=e($p['stream'])?>" maxlength="80"><label>Date of birth</label><input name="date_of_birth" type="date" value="<?=e($p['date_of_birth'])?>"><label>Scholar type</label><select name="scholar_type"><option value="day" <?=$p['scholar_type']==='day'?'selected':''?>>Day</option><option value="boarding" <?=$p['scholar_type']==='boarding'?'selected':''?>>Boarding</option></select><label>Parent / guardian</label><input name="guardian_name" value="<?=e($p['guardian_name'])?>"><label>Guardian phone</label><input name="guardian_phone" value="<?=e($p['guardian_phone'])?>"><button class="button primary" type="submit">Save pupil</button></form></details><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No pupils registered</h3><p>Register a pupil to begin building the school directory.</p></div><?php endif;?></section></div><div class="academic-dialog-actions"><button type="button" class="button" data-close-academic-dialog>Done</button></div></dialog><section class="content-section academic-list-section" data-academic-list><div class="section-heading"><div><div class="eyebrow">ASSESSMENT RECORDS</div><h2>Exams</h2></div><?php if($canResult):?><button type="button" class="button primary" data-open-academic-dialog="exam-add-dialog">Add exam <span aria-hidden="true">+</span></button><?php endif;?></div><?php if($exams):?><div class="academic-table-tools"><label class="sr-only" for="filter-exams">Search exams</label><input id="filter-exams" type="search" data-academic-filter placeholder="Search exam or school" autocomplete="off"><span data-filter-status aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th>Exam name</th><th>Number of pupils</th><th>Actions</th></tr></thead><tbody><?php foreach($exams as $exam):?><tr><td><?=e($exam['name'].' · '.$exam['academic_year'])?><small class="muted"> · <?=e($exam['class_name']?:'All classes')?></small><?php if(count($schools)>1):?><small class="muted"> · <?=e($exam['school_name'])?></small><?php endif;?></td><td><?=number_format((int)$exam['pupil_count'])?></td><td><div class="academic-row-actions"><a class="button primary" href="results.php?exam=<?=$exam['id']?>">View</a><?php if($canResult):?><details class="academic-edit-assignment"><summary class="button">Edit</summary><form method="post" class="academic-async"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="exam_rename"><input type="hidden" name="record_id" value="<?=$exam['id']?>"><input type="hidden" name="school_id" value="<?=$exam['school_id']?>"><input type="hidden" name="old_name" value="<?=e($exam['name'])?>"><input type="hidden" name="old_year" value="<?=$exam['academic_year']?>"><label>Exam name</label><input name="exam_name" value="<?=e($exam['name'])?>" required maxlength="120"><label>Academic year</label><input type="number" name="academic_year" value="<?=$exam['academic_year']?>" min="2000" max="2200" required><button class="button primary" type="submit">Save exam</button></form></details><form method="post" class="academic-async" onsubmit="return confirm('Delete this exam and all its results? This cannot be undone.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="exam_delete"><input type="hidden" name="record_id" value="<?=$exam['id']?>"><input type="hidden" name="school_id" value="<?=$exam['school_id']?>"><button class="button danger" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No exams created</h3><p>Create an exam to organize pupil results for the school year.</p><?php if($canResult):?><button type="button" class="button primary" data-open-academic-dialog="exam-add-dialog">Add exam</button><?php endif;?></div><?php endif;?></section><?php if($canResult):?><dialog class="academic-dialog" id="exam-add-dialog" data-academic-dialog aria-labelledby="exam-add-title"><form method="post" class="note-form academic-async"><div class="academic-dialog-head"><div><div class="eyebrow">ASSESSMENT</div><h2 id="exam-add-title">Add exam</h2><p class="muted">Create an exam record before entering its results.</p></div><button type="button" class="icon-button" data-close-academic-dialog aria-label="Close exam form">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="exam_add"><div class="form-grid"><?=render_school_select('exam-school',$schools)?><div><label for="new-exam-name">Exam name</label><input id="new-exam-name" name="exam_name" required maxlength="120" placeholder="For example, Term 1 examinations"></div><div><label for="new-exam-class">Class scope</label><select id="new-exam-class" name="class_id" data-exam-class-select><option value="">All classes</option><?php foreach($academicClasses as $classOption):?><option value="<?=$classOption['id']?>" data-school-id="<?=$classOption['school_id']?>"><?=e($classOption['name'])?></option><?php endforeach;?></select></div><div><label for="new-exam-year">Academic year</label><input id="new-exam-year" type="number" name="academic_year" min="2000" max="2200" value="<?= (int)date('Y')?>" required></div></div><div class="academic-dialog-actions"><button type="button" class="button" data-close-academic-dialog>Cancel</button><button type="submit" class="button primary">Save exam</button></div></form></dialog><?php endif;?><?php if($canRegister):?><dialog class="academic-dialog" id="register-pupil-dialog" data-academic-dialog aria-labelledby="register-pupil-title"><form method="post" class="note-form academic-async"><div class="academic-dialog-head"><div><div class="eyebrow">PUPIL RECORD</div><h2 id="register-pupil-title">Register a pupil</h2><p class="muted">Enter the pupil’s details to add them to the directory.</p></div><button type="button" class="icon-button" data-close-academic-dialog aria-label="Close registration form">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="pupil"><div class="form-grid"><?=render_school_select('school',$schools)?><div><label for="admission">Admission number</label><input name="admission_number" id="admission" maxlength="60"><small class="muted">Leave blank to generate an admission number.</small></div><div><label for="first">First name</label><input name="first_name" id="first" required maxlength="80"></div><div><label for="middle">Middle name</label><input name="middle_name" id="middle" maxlength="80"></div><div><label for="last">Last name</label><input name="last_name" id="last" required maxlength="80"></div><div><label for="class">Class level</label><input name="class_level" id="class" required maxlength="80" placeholder="Grade 4"></div><div><label for="stream">Stream</label><input name="stream" id="stream" maxlength="80"></div><div><label for="dob">Date of birth</label><input name="date_of_birth" id="dob" type="date"></div><div><label for="scholar">Day or boarding</label><select name="scholar_type" id="scholar"><option value="day">Day scholar</option><option value="boarding">Boarding scholar</option></select></div><div><label for="guardian">Guardian name</label><input name="guardian_name" id="guardian" maxlength="140"></div><div><label for="phone">Guardian phone</label><input name="guardian_phone" id="phone" type="tel" maxlength="30"></div></div><div class="academic-dialog-actions"><button type="button" class="button" data-close-academic-dialog>Cancel</button><button class="button primary" type="submit">Register pupil</button></div></form></dialog><?php endif;?>
<?php endif;?></div></main></div><script>
(()=>{
const page=()=>document.querySelector('.academic-page');
const setupClassAutocomplete=(scope=document)=>{scope.querySelectorAll('form.academic-assignment-form').forEach(form=>{const school=form.querySelector('[name=school_id]'),classInput=form.querySelector('[data-academic-class-input]'),classList=form.querySelector('[data-academic-class-options]'),subjectInput=form.querySelector('[data-academic-subject-input]'),subjectList=form.querySelector('[data-academic-subject-options]'),button=form.querySelector('[type=submit]'),classHint=form.querySelector('[data-class-hint]'),subjectHint=form.querySelector('[data-subject-hint]');if(!school||!classInput||!classList||!subjectInput||!subjectList)return;const allClasses=[...classList.options].map(option=>({name:option.value,school:option.dataset.schoolId}));const allSubjects=[...subjectList.options].map(option=>({name:option.value,school:option.dataset.schoolId,className:option.dataset.className}));const refreshSubjects=clear=>{const exactClass=allClasses.some(item=>item.school===school.value&&item.name.toLocaleLowerCase()===classInput.value.trim().toLocaleLowerCase());const matches=exactClass?allSubjects.filter(item=>item.school===school.value&&item.className.toLocaleLowerCase()===classInput.value.trim().toLocaleLowerCase()):[];subjectList.replaceChildren(...matches.map(item=>{const option=document.createElement('option');option.value=item.name;return option}));if(clear)subjectInput.value='';subjectInput.disabled=matches.length===0;if(subjectHint)subjectHint.textContent=matches.length?'Type to search subjects saved for this class.':'Choose a saved class to see its subjects.';if(button)button.disabled=classInput.disabled||subjectInput.disabled};const refreshClasses=clear=>{const matches=allClasses.filter(item=>school.value&&item.school===school.value);classList.replaceChildren(...matches.map(item=>{const option=document.createElement('option');option.value=item.name;return option}));if(clear)classInput.value='';classInput.disabled=matches.length===0;if(classHint)classHint.textContent=matches.length?'Type to search classes saved for this school.':'No classes have been saved for the selected school.';refreshSubjects(clear);if(button)button.disabled=matches.length===0||subjectInput.disabled};school.addEventListener('change',()=>refreshClasses(true));classInput.addEventListener('input',()=>refreshSubjects(false));classInput.addEventListener('change',()=>refreshSubjects(true));subjectInput.addEventListener('input',()=>{if(button)button.disabled=classInput.disabled||subjectInput.disabled});refreshClasses(false)})};
setupClassAutocomplete();
const setupExamClassSelect=(scope=document)=>{scope.querySelectorAll('[data-exam-class-select]').forEach(select=>{const form=select.closest('form'),school=form?.querySelector('[name=school_id]');if(!school)return;const refresh=()=>{for(const option of select.options){if(!option.value)continue;const otherSchool=!!school.value&&option.dataset.schoolId!==school.value;option.hidden=otherSchool;option.disabled=otherSchool;if(otherSchool&&option.selected)select.value=''}};if(school.tagName==='SELECT')school.addEventListener('change',refresh);refresh()})};
setupExamClassSelect();
const announce=(message,kind='success')=>{let box=document.querySelector('.academic-feedback')||document.querySelector('.academic-page>.notice');if(!box){box=document.createElement('div');box.className='notice academic-feedback';box.setAttribute('role','status');page()?.prepend(box)}if(box){box.classList.toggle('error',kind==='error');box.classList.toggle('success',kind==='success');box.textContent=message}};
document.addEventListener('click',event=>{const open=event.target.closest('[data-open-academic-dialog]');if(open){document.getElementById(open.dataset.openAcademicDialog)?.showModal();return}const close=event.target.closest('[data-close-academic-dialog]');if(close){close.closest('dialog')?.close();return}if(event.target.matches('dialog[data-academic-dialog]'))event.target.close()});
document.addEventListener('input',event=>{const input=event.target.closest('[data-academic-filter]');if(!input)return;const section=input.closest('[data-academic-list]');const query=input.value.trim().toLocaleLowerCase();let visible=0;section?.querySelectorAll('tbody tr').forEach(row=>{const match=row.textContent.toLocaleLowerCase().includes(query);row.hidden=!match;if(match)visible++});const status=section?.querySelector('[data-filter-status]');if(status)status.textContent=query?`${visible} matching records`:''});
document.addEventListener('submit',async event=>{const form=event.target.closest('form.academic-async');if(!form)return;event.preventDefault();const button=event.submitter||form.querySelector('[type=submit]');if(button?.disabled)return;const label=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…'}try{const data=new FormData(form);data.set('_async','1');const response=await fetch(form.getAttribute('action')||location.href,{method:'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'The record could not be saved.');const latest=await fetch(result.url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});if(!latest.ok)throw new Error('Saved, but updated academic data could not be loaded. Refresh the page.');const parsed=new DOMParser().parseFromString(await latest.text(),'text/html');const updated=parsed.querySelector('.academic-page');if(!updated)throw new Error('Saved, but the updated view could not be loaded. Refresh the page.');page()?.replaceWith(updated);history.replaceState({},'',result.url);setupClassAutocomplete(updated);setupExamClassSelect(updated);announce('Academic record saved.')}catch(error){announce(error.message,'error');if(button){button.disabled=false;button.textContent=label||'Save'}}});
})();
</script>
</body></html>

